"""Verified generated bytes staged on the destination filesystem, POSIX only."""

import hashlib
import os

from core import files


def stage_bytes(root, path, data, processor, checkpoint=lambda: None):
    files._staging(path)
    if not root.writable or not 0 < len(data) <= processor.limits.max_output_bytes:
        raise files.FileError("LIMIT_EXCEEDED")
    inspected = processor.inspect(data)
    with root.parent(path, create=True) as (parent, name):
        descriptor = os.open(
            name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=parent
        )
        try:
            for offset in range(0, len(data), files.CHUNK):
                checkpoint()
                remaining = memoryview(data)[offset : offset + files.CHUNK]
                while remaining:
                    count = os.write(descriptor, remaining)
                    if count <= 0:
                        raise files.FileError("FILE_IO")
                    remaining = remaining[count:]
            os.fchmod(descriptor, 0o440)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        os.fsync(parent)
    copied, info = root.read(path, maximum=len(data), checkpoint=checkpoint)
    digest = hashlib.sha256(copied).hexdigest()
    if copied != data or digest != inspected.sha256:
        raise files.FileError("COPY_MISMATCH")
    return files.Stage(path, info, digest, len(data)), inspected
